1656			\,=\, \sum_{\substack{f',f'' \in \deg_{md}(\ell) \\ f' + f'' = f}}
1657			M^{(\mathrm{Line},W),\ell}_{f'} \ot \tau^{W,\ell}_{f''}\,,
